"""
Token services module.

Encapsulates JWT-based token generation and verification logic
for authentication, password reset, and email change.
"""

from itsdangerous import TimedJSONWebSignatureSerializer as Serializer
from flask import current_app

from app.exceptions import ValidationError


class TokenService:
    """Service for generating and verifying JSON Web Tokens."""

    def __init__(self, secret_key: str = None, default_expiration: int = 3600):
        self.secret_key = secret_key or current_app.config['SECRET_KEY']
        self.default_expiration = default_expiration
        self._serializer = None

    def _get_serializer(self) -> Serializer:
        if self._serializer is None:
            self._serializer = Serializer(
                self.secret_key, expires_in=self.default_expiration
            )
        return self._serializer

    def generate_token(self, payload: dict, expiration: int = None) -> str:
        """Generate a signed token from a payload dictionary."""
        serializer = self._get_serializer()
        return serializer.dumps(payload).decode('utf-8')

    def verify_token(self, token: str) -> dict:
        """Verify and decode a token, returning the payload dict.

        Raises:
            ValidationError: if token is invalid or expired.
        """
        serializer = self._get_serializer()
        try:
            return serializer.loads(token.encode('utf-8'))
        except Exception:
            raise ValidationError('Invalid or expired token')


def generate_confirmation_token(user_id: int, expiration: int = 3600) -> str:
    """Generate a confirmation token for a user."""
    service = TokenService()
    return service.generate_token({'confirm': user_id}, expiration)


def confirm_token(token: str, expected_user_id: int) -> bool:
    """Verify a confirmation token and check it matches the expected user ID."""
    service = TokenService()
    try:
        data = service.verify_token(token)
        return data.get('confirm') == expected_user_id
    except ValidationError:
        return False


def generate_reset_token(user_id: int, expiration: int = 3600) -> str:
    """Generate a password reset token for a user."""
    service = TokenService()
    return service.generate_token({'reset': user_id}, expiration)


def verify_reset_token(token: str) -> int:
    """Verify a reset token and return the user ID.

    Raises:
        ValidationError: if token is invalid or expired.
    """
    service = TokenService()
    data = service.verify_token(token)
    return data.get('reset')


def generate_email_change_token(user_id: int, new_email: str, expiration: int = 3600) -> str:
    """Generate an email change confirmation token."""
    service = TokenService()
    return service.generate_token(
        {'change_email': user_id, 'new_email': new_email}, expiration
    )


def verify_email_change_token(token: str) -> tuple:
    """Verify an email change token and return (user_id, new_email).

    Raises:
        ValidationError: if token is invalid or expired.
    """
    service = TokenService()
    data = service.verify_token(token)
    return data.get('change_email'), data.get('new_email')
